Here is the commit message:
smsc75xx: Add workaround for gigabit link up hardware errata.

In certain conditions, the device may not be able to link in gigabit mode. This software workaround ensures that the device will not enter the failure state.

Fixes: d0cad871703b898a442e4049c532ec39168e5b57 ("SMSC75XX USB 2.0 Gigabit Ethernet Devices")
Signed-off-by: Yuiko Oshino <yuiko.oshino@microchip.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The device may fail to establish a gigabit link under certain conditions due to a hardware errata, leading to the device entering a failure state. The workaround implemented in the patch ensures that the PHY is properly initialized and reset, allowing for successful link establishment.

Here is the patch:
 MODULE_PARM_DESC(turbo_mode, "Enable multiple frames per Rx transaction");

+static int smsc75xx_link_ok_nopm(struct usbnet *dev);
+static int smsc75xx_phy_gig_workaround(struct usbnet *dev);
+
 static int __must_check __smsc75xx_read_reg(struct usbnet *dev, u32 index,
 					    u32 *data, int in_pm)
 {
 	u32 buf;
 	int ret;
 	int (*fn)(struct usbnet *, u8, u8, u16, u16, void *, u16);

 	BUG_ON(!dev);

 	if (!in_pm)
 		fn = usbnet_read_cmd;
 	else
 		fn = usbnet_read_cmd_nopm;

 	ret = fn(dev, USB_VENDOR_REQUEST_READ_REGISTER, USB_DIR_IN
 		 | USB_TYPE_VENDOR | USB_RECIP_DEVICE,
 		 0, index, &buf, 4);
 	if (unlikely(ret < 0)) {
 		netdev_warn(dev->net, "Failed to read reg index 0x%08x: %d\n",
 			    index, ret);
 		return ret;
 	}

 	le32_to_cpus(&buf);
 	*data = buf;

 	return ret;
 }


 static int smsc75xx_phy_initialize(struct usbnet *dev)
 {
 	int bmcr, ret, timeout = 0;

 	/* Initialize MII structure */
 	dev->mii.dev = dev->net;
 	dev->mii.mdio_read = smsc75xx_mdio_read;
 	dev->mii.mdio_write = smsc75xx_mdio_write;
 	dev->mii.phy_id_mask = 0x1f;
 	dev->mii.reg_num_mask = 0x1f;
 	dev->mii.supports_gmii = 1;
 	dev->mii.phy_id = SMSC75XX_INTERNAL_PHY_ID;

 	/* reset phy and wait for reset to complete */
 	smsc75xx_mdio_write(dev->net, dev->mii.phy_id, MII_BMCR, BMCR_RESET);

 	do {
 		msleep(10);
 		bmcr = smsc75xx_mdio_read(dev->net, dev->mii.phy_id, MII_BMCR);
 		if (bmcr < 0) {
 			netdev_warn(dev->net, "Error reading MII_BMCR\n");
 			return bmcr;
 		}
 		timeout++;
 	} while ((bmcr & BMCR_RESET) && (timeout < 100));

 	if (timeout >= 100) {
 		netdev_warn(dev->net, "timeout on PHY Reset\n");
 		return -EIO;
 	}

+	/* phy workaround for gig link */
+	smsc75xx_phy_gig_workaround(dev);
+
 	smsc75xx_mdio_write(dev->net, dev->mii.phy_id, MII_ADVERTISE,
 		ADVERTISE_ALL | ADVERTISE_CSMA | ADVERTISE_PAUSE_CAP |
 		ADVERTISE_PAUSE_ASYM);
 	smsc75xx_mdio_write(dev->net, dev->mii.phy_id, MII_CTRL1000,
 		ADVERTISE_1000FULL);

 	/* read and write to clear phy interrupt status */
 	ret = smsc75xx_mdio_read(dev->net, dev->mii.phy_id, PHY_INT_SRC);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Error reading PHY_INT_SRC\n");
 		return ret;
 	}

 	smsc75xx_mdio_write(dev->net, dev->mii.phy_id, PHY_INT_SRC, 0xffff);

 	smsc75xx_mdio_write(dev->net, dev->mii.phy_id, PHY_INT_MASK,
 		PHY_INT_MASK_DEFAULT);
 	mii_nway_restart(&dev->mii);

 	netif_dbg(dev, ifup, dev->net, "phy initialised successfully\n");
 	return 0;
 }


+static int smsc75xx_phy_gig_workaround(struct usbnet *dev)
+{
+	struct mii_if_info *mii = &dev->mii;
+	int ret = 0, timeout = 0;
+	u32 buf, link_up = 0;
+
+	/* Set the phy in Gig loopback */
+	smsc75xx_mdio_write(dev->net, mii->phy_id, MII_BMCR, 0x4040);
+
+	/* Wait for the link up */
+	do {
+		link_up = smsc75xx_link_ok_nopm(dev);
+		usleep_range(10000, 20000);
+		timeout++;
+	} while ((!link_up) && (timeout < 1000));
+
+	if (timeout >= 1000) {
+		netdev_warn(dev->net, "Timeout waiting for PHY link up\n");
+		return -EIO;
+	}
+
+	/* phy reset */
+	ret = smsc75xx_read_reg(dev, PMT_CTL, &buf);
+	if (ret < 0) {
+		netdev_warn(dev->net, "Failed to read PMT_CTL: %d\n", ret);
+		return ret;
+	}
+
+	buf |= PMT_CTL_PHY_RST;
+
+	ret = smsc75xx_write_reg(dev, PMT_CTL, buf);
+	if (ret < 0) {
+		netdev_warn(dev->net, "Failed to write PMT_CTL: %d\n", ret);
+		return ret;
+	}
+
+	timeout = 0;
+	do {
+		usleep_range(10000, 20000);
+		ret = smsc75xx_read_reg(dev, PMT_CTL, &buf);
+		if (ret < 0) {
+			netdev_warn(dev->net, "Failed to read PMT_CTL: %d\n",
+				    ret);
+			return ret;
+		}
+		timeout++;
+	} while ((buf & PMT_CTL_PHY_RST) && (timeout < 100));
+
+	if (timeout >= 100) {
+		netdev_warn(dev->net, "timeout waiting for PHY Reset\n");
+		return -EIO;
+	}
+
+	return 0;
+}
+
 static int smsc75xx_reset(struct usbnet *dev)
 {
 	struct smsc75xx_priv *pdata = (struct smsc75xx_priv *)(dev->data[0]);
 	u32 buf;
 	int ret = 0, timeout;

 	netif_dbg(dev, ifup, dev->net, "entering smsc75xx_reset\n");

 	ret = smsc75xx_wait_ready(dev, 0);
 	if (ret < 0) {
 		netdev_warn(dev->net, "device not ready in smsc75xx_reset\n");
 		return ret;
 	}

 	ret = smsc75xx_read_reg(dev, HW_CFG, &buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to read HW_CFG: %d\n", ret);
 		return ret;
 	}

 	buf |= HW_CFG_LRST;

 	ret = smsc75xx_write_reg(dev, HW_CFG, buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to write HW_CFG: %d\n", ret);
 		return ret;
 	}

 	timeout = 0;
 	do {
 		msleep(10);
 		ret = smsc75xx_read_reg(dev, HW_CFG, &buf);
 		if (ret < 0) {
 			netdev_warn(dev->net, "Failed to read HW_CFG: %d\n", ret);
 			return ret;
 		}
 		timeout++;
 	} while ((buf & HW_CFG_LRST) && (timeout < 100));

 	if (timeout >= 100) {
 		netdev_warn(dev->net, "timeout on completion of Lite Reset\n");
 		return -EIO;
 	}

 	netif_dbg(dev, ifup, dev->net, "Lite reset complete, resetting PHY\n");

 	ret = smsc75xx_read_reg(dev, PMT_CTL, &buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to read PMT_CTL: %d\n", ret);
 		return ret;
 	}

 	buf |= PMT_CTL_PHY_RST;

 	ret = smsc75xx_write_reg(dev, PMT_CTL, buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to write PMT_CTL: %d\n", ret);
 		return ret;
 	}

 	timeout = 0;
 	do {
 		msleep(10);
 		ret = smsc75xx_read_reg(dev, PMT_CTL, &buf);
 		if (ret < 0) {
 			netdev_warn(dev->net, "Failed to read PMT_CTL: %d\n", ret);
 			return ret;
 		}
 		timeout++;
 	} while ((buf & PMT_CTL_PHY_RST) && (timeout < 100));

 	if (timeout >= 100) {
 		netdev_warn(dev->net, "timeout waiting for PHY Reset\n");
 		return -EIO;
 	}

 	netif_dbg(dev, ifup, dev->net, "PHY reset complete\n");

 	ret = smsc75xx_set_mac_address(dev);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to set mac address\n");
 		return ret;
 	}

 	netif_dbg(dev, ifup, dev->net, "MAC Address: %pM\n",
 		  dev->net->dev_addr);

 	ret = smsc75xx_read_reg(dev, HW_CFG, &buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to read HW_CFG: %d\n", ret);
 		return ret;
 	}

 	netif_dbg(dev, ifup, dev->net, "Read Value from HW_CFG : 0x%08x\n",
 		  buf);

 	buf |= HW_CFG_BIR;

 	ret = smsc75xx_write_reg(dev, HW_CFG, buf);
 	if (ret < 0) {
 		netdev_warn(dev->net,  "Failed to write HW_CFG: %d\n", ret);
 		return ret;
 	}

 	ret = smsc75xx_read_reg(dev, HW_CFG, &buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to read HW_CFG: %d\n", ret);
 		return ret;
 	}

 	netif_dbg(dev, ifup, dev->net, "Read Value from HW_CFG after writing HW_CFG_BIR: 0x%08x\n",
 		  buf);

 	if (!turbo_mode) {
 		buf = 0;
 		dev->rx_urb_size = MAX_SINGLE_PACKET_SIZE;
 	} else if (dev->udev->speed == USB_SPEED_HIGH) {
 		buf = DEFAULT_HS_BURST_CAP_SIZE / HS_USB_PKT_SIZE;
 		dev->rx_urb_size = DEFAULT_HS_BURST_CAP_SIZE;
 	} else {
 		buf = DEFAULT_FS_BURST_CAP_SIZE / FS_USB_PKT_SIZE;
 		dev->rx_urb_size = DEFAULT_FS_BURST_CAP_SIZE;
 	}

 	netif_dbg(dev, ifup, dev->net, "rx_urb_size=%ld\n",
 		  (ulong)dev->rx_urb_size);

 	ret = smsc75xx_write_reg(dev, BURST_CAP, buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to write BURST_CAP: %d\n", ret);
 		return ret;
 	}

 	ret = smsc75xx_read_reg(dev, BURST_CAP, &buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to read BURST_CAP: %d\n", ret);
 		return ret;
 	}

 	netif_dbg(dev, ifup, dev->net,
 		  "Read Value from BURST_CAP after writing: 0x%08x\n", buf);

 	ret = smsc75xx_write_reg(dev, BULK_IN_DLY, DEFAULT_BULK_IN_DELAY);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to write BULK_IN_DLY: %d\n", ret);
 		return ret;
 	}

 	ret = smsc75xx_read_reg(dev, BULK_IN_DLY, &buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to read BULK_IN_DLY: %d\n", ret);
 		return ret;
 	}

 	netif_dbg(dev, ifup, dev->net,
 		  "Read Value from BULK_IN_DLY after writing: 0x%08x\n", buf);

 	if (turbo_mode) {
 		ret = smsc75xx_read_reg(dev, HW_CFG, &buf);
 		if (ret < 0) {
 			netdev_warn(dev->net, "Failed to read HW_CFG: %d\n", ret);
 			return ret;
 		}

 		netif_dbg(dev, ifup, dev->net, "HW_CFG: 0x%08x\n", buf);

 		buf |= (HW_CFG_MEF | HW_CFG_BCE);

 		ret = smsc75xx_write_reg(dev, HW_CFG, buf);
 		if (ret < 0) {
 			netdev_warn(dev->net, "Failed to write HW_CFG: %d\n", ret);
 			return ret;
 		}

 		ret = smsc75xx_read_reg(dev, HW_CFG, &buf);
 		if (ret < 0) {
 			netdev_warn(dev->net, "Failed to read HW_CFG: %d\n", ret);
 			return ret;
 		}

 		netif_dbg(dev, ifup, dev->net, "HW_CFG: 0x%08x\n", buf);
 	}

 	/* set FIFO sizes */
 	buf = (MAX_RX_FIFO_SIZE - 512) / 512;
 	ret = smsc75xx_write_reg(dev, FCT_RX_FIFO_END, buf);
 	if (ret < 0) {
 		netdev_warn(dev->net, "Failed to write FCT_RX_FIFO_END: %d\n", ret);
 		return ret;
 	}

 	netif_dbg(dev, ifup, dev->net, "FCT_RX_FIFO_END set to 0x%08x\n", buf);

 	buf = (MAX_TX_FIFO_SIZE - 512) / 512;
